begin;
select plan(15);
select has_column('public','app_settings','audit_record_id','app_settings tiene audit_record_id');
select has_column('public','app_settings','business_settings_version','empresa tiene versión');
select has_column('public','app_settings','catalog_preferences_version','preferencias tiene versión');
select has_function('public','create_sales_agent',array['uuid','text','text','text','text','text']::name[],'existe create_sales_agent con firma pública');
select has_function('public','create_packaging_presentation',array['uuid','text','text','text','text']::name[],'existe create_packaging_presentation con firma pública');
select ok((public.create_sales_agent('11111111-1111-1111-1111-111111111111','Agente pgTAP','', 'test','device','device')) is not null,'crea agente');
select is((public.create_sales_agent('11111111-1111-1111-1111-111111111111','Agente pgTAP','', 'test','device','device')).id,(public.create_sales_agent('11111111-1111-1111-1111-111111111111','Agente pgTAP','', 'test','device','device')).id,'reintento de agente devuelve mismo ID');
select is((select count(*)::integer from public.sales_agents where name='Agente pgTAP'),1,'crea una sola fila de agente');
select ok(has_function_privilege('anon','public.create_sales_agent(uuid,text,text,text,text,text)'::regprocedure,'EXECUTE'),'anon puede ejecutar create_sales_agent');
select ok(has_function_privilege('authenticated','public.create_sales_agent(uuid,text,text,text,text,text)'::regprocedure,'EXECUTE'),'authenticated puede ejecutar create_sales_agent');
select ok(not exists (select 1 from pg_catalog.pg_proc as procedure cross join lateral pg_catalog.aclexplode(coalesce(procedure.proacl,pg_catalog.acldefault('f',procedure.proowner))) as privilege where procedure.oid='public.create_sales_agent(uuid,text,text,text,text,text)'::regprocedure and privilege.grantee=0 and privilege.privilege_type='EXECUTE'),'PUBLIC no puede ejecutar create_sales_agent');
select ok((public.create_packaging_presentation('22222222-2222-2222-2222-222222222222','Presentación pgTAP','test','device','device')) is not null,'crea presentación');
select is((public.create_packaging_presentation('22222222-2222-2222-2222-222222222222','Presentación pgTAP','test','device','device')).id,(public.create_packaging_presentation('22222222-2222-2222-2222-222222222222','Presentación pgTAP','test','device','device')).id,'reintento de presentación devuelve mismo ID');
select is((select count(*)::integer from public.packaging_presentations where name='Presentación pgTAP'),1,'crea una sola presentación');
select ok((select audit_record_id is not null from public.app_settings where id=true),'audit_record_id no nulo');
select * from finish();
rollback;
